        "text": "# -*- coding: utf-8 -*-\r\n\"\"\"\r\n农历 / 节假日（公历 1900-2100）\r\n================================================================\r\n- Cursor(y, m, d)        从某天起逐日给出农历信息，画整月只换算一次\r\n- solar2lunar(y, m, d)   单个公历日期 -> (农历年, 月, 日, 是否闰月)\r\n- cell_label(...)        日历格子第二行文字：节日优先，其次节气，否则农历（初一显示月份）\r\n\r\nINFO 每年一个整数：\r\n  低 4 位       闰月月份（0 表示无闰月）\r\n  0x10000 起    依次表示正月..腊月是否 30 天（1=大月 30 天）\r\n  0x10000       闰月是否 30 天\r\n\"\"\"\r\n\r\ntry:\r\n    from .netsync import days_from_civil\r\nexcept ImportError:\r\n    from netsync import days_from_civil\r\n\r\n# 农历数据 1900-2100（每年一项）\r\nINFO = (\r\n    0x04bd8, 0x04ae0, 0x0a570, 0x054d5, 0x0d260, 0x0d950, 0x16554, 0x056a0, 0x09ad0, 0x055d2,  # 1900-1909\r\n    0x04ae0, 0x0a5b6, 0x0a4d0, 0x0d250, 0x1d255, 0x0b540, 0x0d6a0, 0x0ada2, 0x095b0, 0x14977,  # 1910-1919\r\n    0x04970, 0x0a4b0, 0x0b4b5, 0x06a50, 0x06d40, 0x1ab54, 0x02b60, 0x09570, 0x052f2, 0x04970,  # 1920-1929\r\n    0x06566, 0x0d4a0, 0x0ea50, 0x06e95, 0x05ad0, 0x02b60, 0x186e3, 0x092e0, 0x1c8d7, 0x0c950,  # 1930-1939\r\n    0x0d4a0, 0x1d8a6, 0x0b550, 0x056a0, 0x1a5b4, 0x025d0, 0x092d0, 0x0d2b2, 0x0a950, 0x0b557,  # 1940-1949\r\n    0x06ca0, 0x0b550, 0x15355, 0x04da0, 0x0a5b0, 0x14573, 0x052b0, 0x0a9a8, 0x0e950, 0x06aa0,  # 1950-1959\r\n    0x0aea6, 0x0ab50, 0x04b60, 0x0aae4, 0x0a570, 0x05260, 0x0f263, 0x0d950, 0x05b57, 0x056a0,  # 1960-1969\r\n    0x096d0, 0x04dd5, 0x04ad0, 0x0a4d0, 0x0d4d4, 0x0d250, 0x0d558, 0x0b540, 0x0b6a0, 0x195a6,  # 1970-1979\r\n    0x095b0, 0x049b0, 0x0a974, 0x0a4b0, 0x0b27a, 0x06a50, 0x06d40, 0x0af46, 0x0ab60, 0x09570,  # 1980-1989\r\n    0x04af5, 0x04970, 0x064b0, 0x074a3, 0x0ea50, 0x06b58, 0x055c0, 0x0ab60, 0x096d5, 0x092e0,  # 1990-1999\r\n    0x0c960, 0x0d954, 0x0d4a0, 0x0da50, 0x07552, 0x056a0, 0x0abb7, 0x025d0, 0x092d0, 0x0cab5,  # 2000-2009\r\n    0x0a950, 0x0b4a0, 0x0baa4, 0x0ad50, 0x055d9, 0x04ba0, 0x0a5b0, 0x15176, 0x052b0, 0x0a930,  # 2010-2019\r\n    0x07954, 0x06aa0, 0x0ad50, 0x05b52, 0x04b60, 0x0a6e6, 0x0a4e0, 0x0d260, 0x0ea65, 0x0d530,  # 2020-2029\r\n    0x05aa0, 0x076a3, 0x096d0, 0x04afb, 0x04ad0, 0x0a4d0, 0x1d0b6, 0x0d250, 0x0d520, 0x0dd45,  # 2030-2039\r\n    0x0b5a0, 0x056d0, 0x055b2, 0x049b0, 0x0a577, 0x0a4b0, 0x0aa50, 0x1b255, 0x06d20, 0x0ada0,  # 2040-2049\r\n    0x14b63, 0x09370, 0x049f8, 0x04970, 0x064b0, 0x168a6, 0x0ea50, 0x06b20, 0x1a6c4, 0x0aae0,  # 2050-2059\r\n    0x0a2e0, 0x0d2e3, 0x0c960, 0x0d557, 0x0d4a0, 0x0da50, 0x05d55, 0x056a0, 0x0a6d0, 0x055d4,  # 2060-2069\r\n    0x052d0, 0x0a9b8, 0x0a950, 0x0b4a0, 0x0b6a6, 0x0ad50, 0x055a0, 0x0aba4, 0x0a5b0, 0x052b0,  # 2070-2079\r\n    0x0b273, 0x06930, 0x07337, 0x06aa0, 0x0ad50, 0x14b55, 0x04b60, 0x0a570, 0x054e4, 0x0d160,  # 2080-2089\r\n    0x0e968, 0x0d520, 0x0daa0, 0x16aa6, 0x056d0, 0x04ae0, 0x0a9d4, 0x0a2d0, 0x0d150, 0x0f252,  # 2090-2099\r\n    0x0d520,                                                                                      # 2100\r\n)\r\n\r\nMONTHS = ('正月', '二月', '三月', '四月', '五月', '六月',\r\n          '七月', '八月', '九月', '十月', '冬月', '腊月')\r\n\r\nDAYS = ('初一', '初二', '初三', '初四', '初五', '初六', '初七', '初八', '初九', '初十',\r\n        '十一', '十二', '十三', '十四', '十五', '十六', '十七', '十八', '十九', '二十',\r\n        '廿一', '廿二', '廿三', '廿四', '廿五', '廿六', '廿七', '廿八', '廿九', '三十')\r\n\r\n# 公历固定节日：(月, 日, 名称)\r\nSOLAR_FEST = (\r\n    (1, 1, '元旦'), (2, 14, '情人节'), (3, 8, '妇女节'), (3, 12, '植树节'),\r\n    (4, 1, '愚人节'), (5, 1, '劳动节'), (5, 4, '青年节'), (6, 1, '儿童节'),\r\n    (7, 1, '建党节'), (8, 1, '建军节'), (9, 10, '教师节'), (10, 1, '国庆节'),\r\n    (12, 25, '圣诞节'),\r\n)\r\n\r\n# 农历节日：(农历月, 日, 名称)；除夕按\"腊月最后一天\"单独判断\r\nLUNAR_FEST = (\r\n    (1, 1, '春节'), (1, 15, '元宵'), (2, 2, '龙抬头'),\r\n    (5, 5, '端午'), (7, 7, '七夕'), (7, 15, '中元'),\r\n    (8, 15, '中秋'), (9, 9, '重阳'), (12, 8, '腊八'), (12, 23, '小年'),\r\n)\r\n\r\n_BASE = days_from_civil(1900, 1, 31)      # 农历 1900 年正月初一\r\n\r\n\r\n# ----------------------------- 月/年天数 -----------------------------\r\n\r\ndef leap_month(y):\r\n    \"\"\"闰月月份，0 表示无闰月\"\"\"\r\n    return INFO[y - 1900] & 0xf\r\n\r\n\r\ndef leap_days(y):\r\n    \"\"\"闰月天数，无闰月返回 0\"\"\"\r\n    if INFO[y - 1900] & 0xf:\r\n        return 30 if INFO[y - 1900] & 0x10000 else 29\r\n    return 0\r\n\r\n\r\ndef month_days(y, m):\r\n    \"\"\"农历某月天数（不含闰月）\"\"\"\r\n    return 30 if INFO[y - 1900] & (0x10000 >> m) else 29\r\n\r\n\r\ndef year_days(y):\r\n    \"\"\"农历某年总天数\"\"\"\r\n    v = INFO[y - 1900]\r\n    n = 348\r\n    i = 0x8000\r\n    while i > 0x8:\r\n        if v & i:\r\n            n += 1\r\n        i >>= 1\r\n    return n + leap_days(y)\r\n\r\n\r\n# ----------------------------- 换算 -----------------------------\r\n\r\ndef solar2lunar(y, m, d):\r\n    \"\"\"公历 -> (农历年, 农历月, 农历日, 是否闰月)\"\"\"\r\n    offset = days_from_civil(y, m, d) - _BASE\r\n    if offset < 0:\r\n        return (1900, 1, 1, False)\r\n\r\n    ly = 1900\r\n    while ly < 2100 and offset >= year_days(ly):\r\n        offset -= year_days(ly)\r\n        ly += 1\r\n\r\n    lp = leap_month(ly)\r\n    lm = 1\r\n    is_leap = False\r\n    while lm <= 12:\r\n        md = leap_days(ly) if is_leap else month_days(ly, lm)\r\n        if offset < md:\r\n            break\r\n        offset -= md\r\n        if is_leap:\r\n            is_leap = False\r\n            lm += 1\r\n        elif lm == lp:\r\n            is_leap = True\r\n        else:\r\n            lm += 1\r\n    if lm > 12:                       # 超出 2100 年，兜底\r\n        return (ly, 12, 30, False)\r\n    return (ly, lm, offset + 1, is_leap)\r\n\r\n\r\nclass Cursor:\r\n    \"\"\"逐日遍历农历：next() 返回 (年, 月, 日, 是否闰月)\"\"\"\r\n\r\n    def __init__(self, y, m, d):\r\n        self.year, self.month, self.day, self.leap = solar2lunar(y, m, d)\r\n\r\n    def next(self):\r\n        info = (self.year, self.month, self.day, self.leap)\r\n        self._step()\r\n        return info\r\n\r\n    def _step(self):\r\n        ly = self.year\r\n        md = leap_days(ly) if self.leap else month_days(ly, self.month)\r\n        self.day += 1\r\n        if self.day <= md:\r\n            return\r\n        self.day = 1\r\n        if self.leap:\r\n            self.leap = False\r\n            self.month += 1\r\n            if self.month > 12:\r\n                self.month = 1\r\n                self.year += 1\r\n        elif self.month == leap_month(ly):\r\n            self.leap = True\r\n        else:\r\n            self.month += 1\r\n            if self.month > 12:\r\n                self.month = 1\r\n                self.year += 1\r\n\r\n\r\ndef cell_label(y, m, d, info, jieqi=None):\r\n    \"\"\"日历格子第二行：(文本, 是否节日)。节日优先，其次节气，否则农历，初一显示月份\r\n    jieqi 为当月节气 {日: 名称}，由 jieqi.of_month() 生成\r\n    \"\"\"\r\n    ly, lm, ld, is_leap = info\r\n    if lm == 12 and not is_leap and ld == month_days(ly, 12):\r\n        return ('除夕', True)\r\n    for mm, dd, name in LUNAR_FEST:\r\n        if mm == lm and dd == ld and not is_leap:\r\n            return (name, True)\r\n    for mm, dd, name in SOLAR_FEST:\r\n        if mm == m and dd == d:\r\n            return (name, True)\r\n    if jieqi:\r\n        name = jieqi.get(d)\r\n        if name:\r\n            return (name, True)\r\n    if ld == 1:\r\n        return ((('闰' if is_leap else '') + MONTHS[lm - 1]), False)\r\n    return (DAYS[ld - 1], False)\r\n"
