        "text": "# -*- coding: utf-8 -*-\r\n\"\"\"\r\n网络时间（SNTP）与公历换算\r\n================================================================\r\n- sync()      向公共 NTP 服务器取 UTC 秒数，失败自动换下一个服务器\r\n- set_time()  换算成指定时区的本地时间后写入 RTC，\r\n              之后 time.localtime() 返回的就是本地时间\r\n- 公历换算    纯整数算法（days_from_civil），不依赖 time.mktime()，\r\n              MicroPython 各端口结果一致，也不会踩 2000/1970 纪元差异\r\n\"\"\"\r\n\r\nimport socket\r\n\r\n# NTP 时间戳从 1900-01-01 起算，与 1970-01-01 相差这么多秒\r\nNTP_DELTA = 2208988800\r\n# 依次尝试，前一个失败换下一个\r\nSERVERS = ('ntp.aliyun.com', 'cn.pool.ntp.org', 'ntp.ntsc.ac.cn')\r\n\r\n\r\n# ----------------------------- SNTP -----------------------------\r\n\r\ndef sync(timeout=4):\r\n    \"\"\"获取 UTC 秒数（1970 基准），全部服务器失败返回 None\"\"\"\r\n    for host in SERVERS:\r\n        sock = None\r\n        try:\r\n            addr = socket.getaddrinfo(host, 123)[0][-1]\r\n            sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)\r\n            sock.settimeout(timeout)\r\n            pkt = bytearray(48)\r\n            pkt[0] = 0x1B                       # LI=0 VN=3 Mode=3（客户端请求）\r\n            sock.sendto(pkt, addr)\r\n            data = sock.recv(48)\r\n            if len(data) >= 48:\r\n                secs = ((data[40] << 24) | (data[41] << 16) |\r\n                        (data[42] << 8) | data[43]) - NTP_DELTA\r\n                if 1577836800 < secs < 4102444800:      # 只接受 2020 ~ 2100 之间\r\n                    print('[ntp] %s 同步成功' % host)\r\n                    return secs\r\n                print('[ntp] %s 返回时间不合理' % host)\r\n        except Exception as e:\r\n            print('[ntp] %s 失败: %s' % (host, e))\r\n        finally:\r\n            if sock is not None:\r\n                try:\r\n                    sock.close()\r\n                except Exception:\r\n                    pass\r\n    return None\r\n\r\n\r\ndef set_time(utc_secs, tz_hours=8):\r\n    \"\"\"UTC 秒数 -> 本地时间写入 RTC，返回 (年, 月, 日, 时, 分, 秒)\"\"\"\r\n    try:\r\n        offset = int(round(tz_hours * 3600))\r\n    except Exception:\r\n        offset = 8 * 3600\r\n\r\n    local = int(utc_secs) + offset\r\n    days = local // 86400\r\n    sod = local - days * 86400\r\n    y, m, d = civil_from_days(days)\r\n    wd = (days + 3) % 7                 # 1970-01-01 是周四，周一记 0\r\n    hh = sod // 3600\r\n    mi = (sod % 3600) // 60\r\n    ss = sod % 60\r\n\r\n    try:\r\n        import machine\r\n        rtc = machine.RTC()\r\n        try:\r\n            rtc.datetime((y, m, d, wd, hh, mi, ss, 0))\r\n        except Exception:\r\n            # 少数端口的 RTC 不收 weekday 字段\r\n            rtc.datetime((y, m, d, hh, mi, ss, 0))\r\n    except Exception as e:\r\n        print('[ntp] 写入 RTC 失败:', e)\r\n    return (y, m, d, hh, mi, ss)\r\n\r\n\r\n# --------------------------- 公历换算 ---------------------------\r\n\r\ndef civil_from_days(z):\r\n    \"\"\"自 1970-01-01 起的天数 -> (年, 月, 日)\"\"\"\r\n    z += 719468\r\n    era = (z if z >= 0 else z - 146096) // 146097\r\n    doe = z - era * 146097\r\n    yoe = (doe - doe // 1460 + doe // 36524 - doe // 146096) // 365\r\n    y = yoe + era * 400\r\n    doy = doe - (365 * yoe + yoe // 4 - yoe // 100)\r\n    mp = (5 * doy + 2) // 153\r\n    d = doy - (153 * mp + 2) // 5 + 1\r\n    m = mp + 3 if mp < 10 else mp - 9\r\n    return (y + (1 if m <= 2 else 0), m, d)\r\n\r\n\r\ndef days_from_civil(y, m, d):\r\n    \"\"\"(年, 月, 日) -> 自 1970-01-01 起的天数\"\"\"\r\n    y -= 1 if m <= 2 else 0\r\n    era = (y if y >= 0 else y - 399) // 400\r\n    yoe = y - era * 400\r\n    doy = (153 * (m + (-3 if m > 2 else 9)) + 2) // 5 + d - 1\r\n    doe = yoe * 365 + yoe // 4 - yoe // 100 + doy\r\n    return era * 146097 + doe - 719468\r\n\r\n\r\ndef weekday(y, m, d):\r\n    \"\"\"星期：0=周一 ... 6=周日\"\"\"\r\n    return (days_from_civil(y, m, d) + 3) % 7\r\n\r\n\r\ndef days_in_month(y, m):\r\n    if m == 2:\r\n        return 29 if (y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)) else 28\r\n    return 30 if m in (4, 6, 9, 11) else 31\r\n\r\n\r\ndef iso_week(y, m, d):\r\n    \"\"\"ISO 8601 周序号（周一为每周第一天）\"\"\"\r\n    days = days_from_civil(y, m, d)\r\n    wd = (days + 3) % 7\r\n    th = days - wd + 3                  # 本周周四\r\n    ty = civil_from_days(th)[0]\r\n    return (th - days_from_civil(ty, 1, 1)) // 7 + 1\r\n\r\n\r\ndef shift_month(y, m, delta):\r\n    \"\"\"按月偏移，返回 (年, 月)\"\"\"\r\n    idx = y * 12 + (m - 1) + delta\r\n    return (idx // 12, idx % 12 + 1)\r\n"
