        "text": "\nimport gc\nimport json\nimport machine\nimport os\nimport sys\nimport time\n\nDEFAULT_KEY = '默认应用'\n\n# ----------------- 全局状态 -----------------\n_default='manage'\n\n\ndef _load_json(path):\n    try:\n        with open(path) as f:\n            return json.loads(f.read())\n    except (OSError, ValueError) as e:\n        print('[manage] 读取失败:', path, e)\n        return None\n\n\ndef _load_default():\n    \"\"\"从 device.json 读默认应用标识，文件不存在则视为未设置\"\"\"\n    global _default\n    path = 'device.json'\n    cfg = _load_json(path)\n    if not isinstance(cfg, dict):\n        cfg = {}\n    _default = str(cfg.get(DEFAULT_KEY) or cfg.get('default_app') or '')\n    return _default\n\n\ndef _run_app(entry):\n    code = 'from '+entry+' import '+entry+'\\n'\n    code = code+'try:\\n'\n    code = code+'    '+entry+'.main()\\n'\n    code = code+'except:\\n'\n    code = code+'    pass'\n    try:\n        with open('app.py', 'r') as f:\n            if code not in f.read():\n                try:\n                    with open('app.py', 'w') as f:\n                        f.write(code)\n                except OSError as e:\n                    print('[manage] 写入 device.json 失败:', e)\n                    return False        \n    except:\n        try:\n            with open('app.py', 'w') as f:\n                f.write(code)\n        except OSError as e:\n            print('[manage] 写入 device.json 失败:', e)\n            return False\n    import app\n\n\n\n# ----------------- 按键 -----------------\n\n# 按键引脚（低电平触发）\nKEY_UP = 40\nKEY_DOWN = 39\n\n# ----------------- 入口 -----------------\n\ndef _boot_key_pressed():\n    \"\"\"开机窗口内检测上/下键（GPIO40/GPIO39）是否被按住\"\"\"\n    try:\n        up = machine.Pin(KEY_UP, machine.Pin.IN, machine.Pin.PULL_UP)\n        down = machine.Pin(KEY_DOWN, machine.Pin.IN, machine.Pin.PULL_UP)\n        n_up = 0\n        n_down = 0\n        for _ in range(20):        # 约 200 ms 窗口，连续 3 次低电平视为按下\n            n_up = n_up + 1 if up.value() == 0 else 0\n            n_down = n_down + 1 if down.value() == 0 else 0\n            if n_up >= 3 or n_down >= 3:\n                return True\n            time.sleep_ms(10)\n    except Exception as e:\n        print('[manage] 开机按键检测失败:', e)\n    return False\ndef run_manage():\n    from manage import manage\n    manage.main()\n\ndef main():\n    \"\"\"开机入口：按住 GPIO39/GPIO40 强制进管理器，否则先启动默认应用\"\"\"\n    try:\n        _load_default()\n    except:\n        run_manage()\n        return\n    if _boot_key_pressed():\n        print('[manage] 开机按住 GPIO39/40，跳过默认应用，强制进入应用管理器')\n        run_manage()\n        return\n    _run_app(_default)\n\n\n\nif __name__ == '__main__':\n    main()\n\n\n"
