        "text": "\"\"\"\n按键事件:BOOT 键唤醒/打断。\n- 短按: 触发对话(唤醒)\n- 长按: 打断当前回答\n\"\"\"\n\nfrom machine import Pin\nimport time\nfrom . import utils\n\nfrom . import config\n\n\n# 设备状态常量(供 ButtonManager 上报)\nEVENT_SHORT_PRESS = \"short_press\"\nEVENT_LONG_PRESS = \"long_press\"\n\n\nclass ButtonManager:\n    def __init__(self, on_event=None):\n        self.pin = Pin(config.BUTTON_PIN, Pin.IN, Pin.PULL_UP)\n        self.on_event = on_event\n        self._press_start = 0\n        self._pressed = False\n        self._last_event = 0\n\n    def poll(self):\n        \"\"\"主循环轮询按键,返回事件字符串或 None。\n        兼容没有中断的板子,使用轮询方式更稳。\n        长按采用\"按下持续超过阈值即触发\",且只触发一次。\n        \"\"\"\n        val = self.pin.value()  # 上拉:松开为 1,按下为 0\n        now = time.ticks_ms()\n        if val == 0 and not self._pressed:\n            # 按下边沿\n            if time.ticks_diff(now, self._last_event) < config.BUTTON_DEBOUNCE_MS:\n                return None\n            self._pressed = True\n            self._press_start = now\n            self._long_fired = False\n            self._last_event = now\n            return None\n\n        if val == 1 and self._pressed:\n            # 松开边沿\n            duration = time.ticks_diff(now, self._press_start)\n            self._pressed = False\n            self._last_event = now\n            # 若长按已提前触发,松开时不再产生事件\n            if getattr(self, \"_long_fired\", False):\n                self._long_fired = False\n                return None\n            if duration >= config.BUTTON_LONG_PRESS_MS:\n                event = EVENT_LONG_PRESS\n            elif duration >= config.BUTTON_SHORT_PRESS_MS:\n                event = EVENT_SHORT_PRESS\n            else:\n                # 抖动\n                return None\n            utils.log(\"Button: {} ({}ms)\", event, duration)\n            if self.on_event:\n                try:\n                    self.on_event(event)\n                except Exception as e:\n                    utils.log(\"Button: event cb err {}\", e)\n            return event\n\n        # 处于按下状态时,如果已超过长按阈值,提前触发长按事件(只一次)\n        if self._pressed and not getattr(self, \"_long_fired\", False):\n            duration = time.ticks_diff(now, self._press_start)\n            if duration >= config.BUTTON_LONG_PRESS_MS:\n                self._long_fired = True\n                utils.log(\"Button: long_press (live, {}ms)\", duration)\n                if self.on_event:\n                    try:\n                        self.on_event(EVENT_LONG_PRESS)\n                    except Exception as e:\n                        utils.log(\"Button: event cb err {}\", e)\n                return EVENT_LONG_PRESS\n        return None\n"
