        "path": "config.py",
        "size": 4491,
        "text": "\"\"\"\n小智AI MicroPython 客户端配置文件\n用户在此修改 WiFi、服务器、引脚等参数。\n\"\"\"\n\n# ============================== WiFi 配置 ==============================\nWIFI_SSID = \"YourWiFiSSID\"\nWIFI_PASSWORD = \"YourWiFiPassword\"\n# WiFi 连接超时(秒)\nWIFI_CONNECT_TIMEOUT = 30\n# 配网失败后是否开启 AP 模式以便用户通过网页配置\nWIFI_AP_FALLBACK = True\n# AP 模式 SSID (回退配网用)\nWIFI_AP_SSID = \"XiaoZhi-Setup\"\n# AP 模式密码(必须 >= 8 字符)\nWIFI_AP_PASSWORD = \"12345678\"\n\n# ============================== 服务器配置 ==============================\n# OTA 激活接口(对齐 PC 版,使用 tenclass.net)\nOTA_URL = \"https://api.tenclass.net/xiaozhi/ota/\"\n# WebSocket 服务端 URL(对齐 PC 版,可留空则从 OTA 响应获取)\nWEBSOCKET_URL = \"wss://api.tenclass.net/xiaozhi/v1/\"\n# 协议版本号:对齐 py-xiaozhi PC 客户端(plain text/binary,无二进制头)\nPROTOCOL_VERSION = 1\n# 设备型号,用于 OTA 接口上报\nDEVICE_MODEL = \"micropython-generic\"\n# 设备出厂编号(留空则用 MAC 地址)\nDEVICE_SN = \"\"\n# 固件版本\nFIRMWARE_VERSION = \"1.0.0-micropython\"\n\n# access token(对齐 PC 版:留空则走 OTA 激活流程获取)\n# 若使用自建服务器可直接填 test-token\nACCESS_TOKEN = \"\"\n\n# ============================== 音频编码配置 ==============================\n# 编码格式: \"opus\" 或 \"pcm\"\n# - \"opus\":  官方 xiaozhi.me 后端要求,需用户自行编译带 Opus 模块的固件\n#           (参考 lib/opus.c 说明),否则会回退为 PCM 并打印警告\n# - \"pcm\":   直接传输 16kHz/16bit/mono PCM,仅自建后端(xiaozhi-esp32-server)支持\nAUDIO_CODEC = \"opus\"\n\n# 采样率\n# 官方 xiaozhi.me 要求 16kHz(对齐 ESP32 固件 GetHelloMessage)\nAUDIO_SAMPLE_RATE = 16000\n# 声道数\nAUDIO_CHANNELS = 1\n# 采样位宽(16 bit)\nAUDIO_BITS = 16\n# Opus 帧时长(ms): 60 对应官方默认,可选 20/40/60\nOPUS_FRAME_DURATION_MS = 60\n# PCM 单帧采样数(每帧时长 = 1000 * FRAME_SAMPLES / SAMPLE_RATE)\n# 60ms @ 16kHz = 960 samples(对齐 ESP32 固件)\nFRAME_SAMPLES = 960\n# Opus 编解码器调优参数(对齐 78/xiaozhi-esp32 固件推荐值)\n# 平均比特率(bps),语音 24000-40000 合理;越高音质越好但越费流量\nOPUS_BITRATE = 30000\n# 复杂度 1-10,ESP32 单核建议 2-4;过高会丢帧\nOPUS_COMPLEXITY = 3\n# 启用 DTX(静音不发数据,省流但服务器可能误判无声)\nOPUS_DTX = False\n# 假设丢包率(%),用于驱动 FEC 编码强度\nOPUS_PACKET_LOSS_PERC = 5\n# I2S 缓冲区帧数\nI2S_BUFFER_FRAMES = 8\n\n# ============================== I2S 引脚配置 ==============================\n# 通用可配置:按常见 ESP32-S3 面包板 DIY 接线\n# INMP441 麦克风(I2S 输入)\nI2S_MIC_BCK = 5      # BCLK\nI2S_MIC_WS = 4       # LRCLK/WS\nI2S_MIC_DATA_IN = 6  # DIN\n# MAX98357 功放(I2S 输出)\nI2S_SPK_BCK = 15     # BCLK\nI2S_SPK_WS = 16      # LRCLK/WS\nI2S_SPK_DATA_OUT = 7 # DOUT\n\n# ============================== 按键配置 ==============================\n# BOOT 按键 GPIO (ESP32-S3 默认 GPIO0)\nBUTTON_PIN = 0\n# 短按阈值(毫秒):按下短于此为短按 -> 触发对话\nBUTTON_SHORT_PRESS_MS = 50\n# 长按阈值(毫秒):按住长于此为长按 -> 中断当前回答\nBUTTON_LONG_PRESS_MS = 500\n# 按键防抖(毫秒)\nBUTTON_DEBOUNCE_MS = 30\n\n# ============================== OLED 显示配置 ==============================\n# 启用 OLED 显示(SSD1306 128x64 I2C)\nOLED_ENABLED = False\n# I2C 引脚\nOLED_SDA = 41\nOLED_SCL = 42\n# I2C 频率(Hz)\nOLED_I2C_FREQ = 400000\n# OLED I2C 地址(通常 0x3C,部分模块为 0x3D)\nOLED_I2C_ADDR = 0x3C\n# 屏幕宽高\nOLED_WIDTH = 128\nOLED_HEIGHT = 64\n\n# ============================== 墨水屏显示配置 ==============================\n# 启用 4.2 寸三色墨水屏(GDEY042Z98 / SSD1683,400x300,SPI)\nEPD_ENABLED = True\n# 注意:墨水屏按 EPD() 默认参数初始化,引脚由 driver/epd4in2b.py 决定:\n#   cs=9, dc=3, rst=8, busy=10, sclk=17, mosi=18,\n#   spi_id=2, baudrate=25MHz, busy_active_high=True\n# 如需改引脚,直接改驱动里的 __init__ 默认值。\n# 两次刷新最小间隔(毫秒),墨水屏刷新慢,避免频繁闪烁\nEPD_MIN_REFRESH_MS = 2000\n\n# ============================== 行为开关 ==============================\n# 自动连续对话(回答结束自动重新进入 listening)\nAUTO_CONTINUE = False\n# 监听静音自动停止(秒),0 表示不自动停止\n# auto 模式下由服务器 VAD 控制,无需客户端超时\nLISTEN_SILENCE_TIMEOUT = 0\n# 调试日志\nDEBUG = True\n"
