        "text": "\"\"\"\n通用工具函数:设备ID、UUID、JSON、日志。\n依赖: binascii, os, json, machine, time\n\"\"\"\n\nimport binascii\nimport os\nimport json\nimport machine\nimport time\n\n\ndef log(msg, *args):\n    \"\"\"带时间戳的日志输出\"\"\"\n    from . import config\n    if not getattr(config, \"DEBUG\", False):\n        return\n    t = time.ticks_ms()\n    secs = (t // 1000) % 60\n    mins = (t // 60000) % 60\n    hours = (t // 3600000) % 24\n    prefix = \"{:02d}:{:02d}:{:02d}\".format(hours, mins, secs)\n    if args:\n        try:\n            msg = msg.format(*args)\n        except Exception:\n            msg = str(msg) + \" \" + \" \".join(str(a) for a in args)\n    print(\"[{}] {}\".format(prefix, msg))\n\n\ndef get_mac_bytes():\n    \"\"\"获取设备 MAC 地址(6 字节)\"\"\"\n    return machine.unique_id()\n\n\ndef get_mac_string():\n    \"\"\"获取 MAC 字符串(hex 小写无分隔)\"\"\"\n    return binascii.hexlify(get_mac_bytes()).decode()\n\n\ndef get_device_id():\n    \"\"\"设备 ID: 小智协议中用作 Device-Id 头,使用冒号分隔的 MAC 地址\n    对齐 PC 版格式: 1a:b2:c3:d4:e5:f7\n    \"\"\"\n    mac = get_mac_bytes()\n    return \":\".join(\"{:02x}\".format(b) for b in mac)\n\n\ndef get_client_id():\n    \"\"\"Client-Id: 软件 UUID,固化在设备存储中\"\"\"\n    client_id = read_nvs(\"client_id\")\n    if client_id:\n        return client_id\n    # 生成随机 UUID v4\n    client_id = uuid4()\n    write_nvs(\"client_id\", client_id)\n    return client_id\n\n\ndef uuid4():\n    \"\"\"生成 UUID v4 字符串(尽力而为;MicroPython 无强熵源时退化为时间+MAC 哈希)\"\"\"\n    b = bytearray(16)\n    # 优先使用 os.urandom(MicroPython ESP32 通常支持)\n    rnd = None\n    try:\n        rnd = os.urandom(16)\n    except Exception:\n        rnd = None\n    if rnd and len(rnd) == 16:\n        for i in range(16):\n            b[i] = rnd[i]\n    else:\n        # 退路:时间 + MAC + 自增计数器哈希\n        t = time.ticks_us()\n        mac = get_mac_bytes()\n        cnt = 0\n        for i in range(16):\n            cnt += 1\n            b[i] = (t >> (i % 8)) & 0xFF\n            b[i] ^= mac[i % len(mac)]\n            b[i] ^= cnt & 0xFF\n    # v4 标记位\n    b[6] = (b[6] & 0x0F) | 0x40\n    b[8] = (b[8] & 0x3F) | 0x80\n    h = binascii.hexlify(bytes(b)).decode()\n    return \"{}-{}-{}-{}-{}\".format(h[0:8], h[8:12], h[12:16], h[16:20], h[20:32])\n\n\n# ============================== NVS 存储封装 ==============================\n# MicroPython 无 NVS,使用文件系统模拟\n_NVS_FILE = \"xiaozhi/nvs.json\"\n\n\ndef _load_nvs():\n    try:\n        with open(_NVS_FILE, \"r\") as f:\n            return json.loads(f.read())\n    except Exception:\n        return {}\n\n\ndef _save_nvs(d):\n    try:\n        with open(_NVS_FILE, \"w\") as f:\n            f.write(json.dumps(d))\n        return True\n    except Exception as e:\n        log(\"NVS save failed: {}\", e)\n        return False\n\n\ndef read_nvs(key, default=None):\n    return _load_nvs().get(key, default)\n\n\ndef write_nvs(key, value):\n    d = _load_nvs()\n    d[key] = value\n    return _save_nvs(d)\n\n\ndef clear_nvs():\n    try:\n        os.remove(_NVS_FILE)\n    except Exception:\n        pass\n\n\n# ============================== JSON 辅助 ==============================\ndef dumps(obj):\n    return json.dumps(obj)\n\n\ndef loads(s):\n    if isinstance(s, (bytes, bytearray)):\n        s = s.decode(\"utf-8\", \"ignore\")\n    return json.loads(s)\n\n\ndef now_ms():\n    return time.ticks_ms()\n\n\ndef ticks_diff_ms(a, b):\n    return time.ticks_diff(a, b)\n"
