        "text": "\"\"\"\nWiFi 连接管理:连接 STA、AP 回退配网。\n\"\"\"\n\nimport network\nimport time\nimport socket\nimport gc\nfrom . import utils\n\nfrom . import config\n\n\nclass WiFiManager:\n    def __init__(self):\n        self.sta = network.WLAN(network.STA_IF)\n        self.ap = network.WLAN(network.AP_IF)\n        self.connected = False\n        self.ip = None\n\n    def connect(self):\n        \"\"\"连接 WiFi(仅 STA)。失败返回 False,是否进入 AP 配网由调用方决定。\"\"\"\n        utils.log(\"WiFi: connecting to {}\", config.WIFI_SSID)\n        self.sta.active(True)\n        self.ap.active(False)\n        if self.sta.isconnected():\n            utils.log(\"WiFi: already connected\")\n            self.connected = True\n            self.ip = self.sta.ifconfig()[0]\n            return True\n\n        if not is_configured():\n            utils.log(\"WiFi: SSID not configured, need AP config\")\n            return False\n\n        self.sta.connect(config.WIFI_SSID, config.WIFI_PASSWORD)\n        t0 = time.ticks_ms()\n        while not self.sta.isconnected():\n            if time.ticks_diff(time.ticks_ms(), t0) > config.WIFI_CONNECT_TIMEOUT * 1000:\n                utils.log(\"WiFi: connect timeout\")\n                return False\n            time.sleep_ms(200)\n\n        self.connected = True\n        self.ip = self.sta.ifconfig()[0]\n        utils.log(\"WiFi: connected ip={}\", self.ip)\n        gc.collect()\n        return True\n\n    def start_ap(self):\n        \"\"\"启动 AP 模式供网页配网,返回 (ip, ssid, password)\"\"\"\n        utils.log(\"WiFi: starting AP {}\", config.WIFI_AP_SSID)\n        self.ap.active(True)\n        # AP 密码必须 >=8 字符,否则 ESP32 报 \"Wifi Invalid Password\"\n        ap_password = getattr(config, \"WIFI_AP_PASSWORD\", \"12345678\")\n        self.ap.config(essid=config.WIFI_AP_SSID, password=ap_password, authmode=4)\n        ip = self.ap.ifconfig()[0]\n        utils.log(\"WiFi: AP ip={} ssid={} pass={}\", ip, config.WIFI_AP_SSID, ap_password)\n        return ip, config.WIFI_AP_SSID, ap_password\n\n    def start_config_portal(self, ip):\n        \"\"\"在 AP 模式下提供网页让用户提交 SSID/密码并保存\"\"\"\n        s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)\n        s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)\n        s.bind((\"0.0.0.0\", 80))\n        s.listen(1)\n        utils.log(\"WiFi: config portal at http://{}/\", ip)\n        # 阻塞直到收到配网请求; 重启后生效\n        while True:\n            try:\n                conn, addr = s.accept()\n                req = conn.recv(1024).decode(\"utf-8\", \"ignore\")\n                utils.log(\"WiFi: HTTP from {}\", addr)\n                if \"POST /save\" in req:\n                    # 解析 body\n                    body = req.split(\"\\r\\n\\r\\n\", 1)[-1]\n                    params = {}\n                    for kv in body.split(\"&\"):\n                        if \"=\" in kv:\n                            k, v = kv.split(\"=\", 1)\n                            # 简单 URL 解码(避免依赖 urllib.parse)\n                            v = v.replace(\"+\", \" \").replace(\"%21\", \"!\") \\\n                                 .replace(\"%2F\", \"/\").replace(\"%40\", \"@\") \\\n                                 .replace(\"%2B\", \"+\").replace(\"%3A\", \":\") \\\n                                 .replace(\"%3D\", \"=\").replace(\"%26\", \"&\")\n                            params[k] = v\n                    if \"ssid\" in params and \"password\" in params:\n                        utils.write_nvs(\"wifi_ssid\", params[\"ssid\"])\n                        utils.write_nvs(\"wifi_password\", params[\"password\"])\n                        conn.send(\"HTTP/1.1 200 OK\\r\\nContent-Type: text/html\\r\\n\\r\\n\"\n                                  \"<h1>Saved. Rebooting...</h1>\")\n                        conn.close()\n                        time.sleep(1)\n                        machine_reset()\n                conn.send(self._portal_html())\n                conn.close()\n            except Exception as e:\n                utils.log(\"WiFi: portal err {}\", e)\n                time.sleep(0.5)\n\n    def _portal_html(self):\n        return (\n            \"HTTP/1.1 200 OK\\r\\nContent-Type: text/html\\r\\n\\r\\n\"\n            \"<!DOCTYPE html><html><head><meta charset='utf-8'>\"\n            \"<title>XiaoZhi Setup</title></head>\"\n            \"<body style='font-family:sans-serif;padding:20px'>\"\n            \"<h2>XiaoZhi WiFi Setup</h2>\"\n            \"<form method='POST' action='/save'>\"\n            \"SSID:<br><input name='ssid' maxlength='32'><br><br>\"\n            \"Password:<br><input name='password' type='password' maxlength='64'><br><br>\"\n            \"<button type='submit'>Save &amp; Reboot</button>\"\n            \"</form></body></html>\"\n        )\n\n    def is_connected(self):\n        return self.connected and self.sta.isconnected()\n\n    def get_ip(self):\n        return self.ip\n\n\ndef machine_reset():\n    \"\"\"硬重启\"\"\"\n    import machine\n    machine.reset()\n\n\ndef load_saved_wifi():\n    \"\"\"从 NVS 读取配网时保存的 SSID/密码并写回 config\"\"\"\n    ssid = utils.read_nvs(\"wifi_ssid\")\n    pwd = utils.read_nvs(\"wifi_password\")\n    if ssid:\n        config.WIFI_SSID = ssid\n        config.WIFI_PASSWORD = pwd or \"\"\n        return True\n    return False\n\n\ndef is_configured():\n    \"\"\"是否已配置 WiFi(排除模板占位值)\"\"\"\n    ssid = getattr(config, \"WIFI_SSID\", \"\")\n    return bool(ssid) and ssid != \"YourWiFiSSID\"\n"
