        "text": "\"\"\"\n小智 AI MicroPython 客户端 - 功能入口\n外部使用: from xiaozhi import xiaozhi; xiaozhi.main()\n\"\"\"\n\nimport gc\nfrom .app import Application\nfrom . import utils\n\n\ndef main():\n    \"\"\"启动小智 AI 语音对话客户端(阻塞运行)。\"\"\"\n    gc.enable()\n    gc.collect()\n    utils.log(\"=== XiaoZhi MicroPython Client ===\")\n    app = Application()\n    app.run()\n\n\nif __name__ == \"__main__\":\n    main()\n"
